  hl_ceil L <= sp - 128 -> sp <= hl_sptop L -> (n = 0 \/ (hl_ceil L <= x /\ x + n <= hl_sptop L)) ->
  (m = 0 \/ (In (B, bm) LB /\ B <= y /\ y + m <= B + bm)) ->
